INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Pals Bubble Pop', 'Help Kat blast and pop through levels of fun in this bubble shooter puzzle game! Match three or more bubbles and blast your way through each puzzle to rescue your friends! Collect powerups to help shoot the bubbles to pop your way through each challenging puzzle in this AMAZING bubble shooting quest adventure! Simple and easy controls, aim assist and power ups to help you align your bubbles for the perfect shot and shoot bubbles with ease. Over 100 levels of fun!' FROM games WHERE igdb_id = 147590 ON CONFLICT (game_id, language_code) DO NOTHING;
