INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('be-a-walker--1', 147489, '2020-02-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co48wc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9l7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BE-A Walker', 'You are the pilot of a battle mech BE-A Walker (Biped Enhanced Assault Walker). Your mission is to defeat the hostile natives to protect the colony population. But annihilation of the native race is not the only way to stop the war. Choose your side and make the decision that suits you best: to be a human, a true son of Earth fighting for survival of your race and killing whoever stands in your way, or to be a humanist who’s trying to protect the poor natives, victims of the greedy invaders. Controlling the mech is not an easy thing. Raise up one leg, move it to the left or to the right, and then take a step. Repeat it for the other one. This is how the Walker walks. Control every leg to smash the enemies or to avoid grenades and missiles. Key features: - Seamlessly generated world - The weirdest and most cruel walking simulator out there - Upgrade your mech and weapons to become more dangerous - Defeat the natives or lead them in their effort to protect their homeworld' FROM games WHERE igdb_id = 147489 ON CONFLICT (game_id, language_code) DO NOTHING;
