INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candy Jump featuring Frosty', 'Direct Frosty the jumping snowman through unlimited frozen candyland puzzles as he climbs higher and you reach high scores! Use your snowflake coins to buy design your own snowman or get new frosty friends. Play as Mrs. Frosty, Santa Snowman and Reindeer Snowman! Endless levels plus additional snowman characters make this a never-ending puzzle to jump your way through. Just keep your eyes on the sky for angry candy monsters. Children, as well as adults, will enjoy this simple, yet challenging jump game. Make winter snow and snowmen a year round frozen experience for your family.' FROM games WHERE igdb_id = 147131 ON CONFLICT (game_id, language_code) DO NOTHING;
