INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maid Mansion', 'Maid Mansion is an eroge-thriller visual novel set shortly after the Great War, developed by Crazy Cactus Entertainment. A young man inherits his relative''s mansion after their untimely death. Now he is the lord of the manor, with only one restriction left upon his grandfather''s passing - he may never fire the head maid, Takako.' FROM games WHERE igdb_id = 25826 ON CONFLICT (game_id, language_code) DO NOTHING;
