INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Derk''s Mutant Battlegrounds', 'This is a game where you train Derklings, a creature with a neural network brain, to fight for you! The game takes place in a wonky western-themed MOBA setting, and as you battle other players you earn upgrades and items for your Derklings. The challenge is to figure out the best loadout and training strategy for your Derklings!' FROM games WHERE igdb_id = 120604 ON CONFLICT (game_id, language_code) DO NOTHING;
