INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('retro-arcade-shooter-attack-from-pluto', 147863, '2020-08-07', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/arber.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Retro Arcade Shooter - Attack from Pluto', 'Get three classic arcade space shooter games in one game! Blast your way into the future or is it really the past since this retro arcade space shooter returns you to the classic age (or glory days) of arcade games. Retro shooter action combined with updated graphics make this a must have for any arcade fan. Random* enemy spaceships and killer bosses make this game an unbelievable endless challenge. Collect as many powerups as you can to beef up your fire power and increase your chances of survival. Play all three games because each one is different and see how you do. Blast away!' FROM games WHERE igdb_id = 147863 ON CONFLICT (game_id, language_code) DO NOTHING;
