INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wst-snooker', 175858, '2020-07-30', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WST Snooker', 'WST Snooker is the official video game of the World Snooker Tour and the most authentic simulation of the sport ever crafted. Play in every officially licensed tournament as any of the top 128 players in the world including: Judd Trump, Mark Selby, Ronnie O’Sullivan, Ding Junhui and legends of the sport like Ken Doherty and Jimmy White. Choose from a fantastic mix of online modes, from quick play online match-making to global online tournaments that link in real-time with the live World Snooker Tour. Feel the emotion and drama of every match as you join the World Snooker Tour and compete in all 25 snooker tournaments around the globe - from the China Open at Beijing’s Olympic Gymnasium, to The Masters at Alexandra Palace in London and, the pinnacle, the legendary Crucible Theatre for the World Snooker Championship. In WST Snooker’s immersive career mode players can rise through the ranks as they play against the top 128 players in the world, including Ronnie “The Rocket” O’Sullivan, “the Star of the East” Ding Junhui, Judd “The Ace” Trump, “the Wizard of Wishaw” John Higgins and the “Jester from Leicester”, Mark Selby! A first of it’s kind simulation for mobile and based on the smash hit Snooker19 for PC and Console, WST Snooker has the most detailed true-to-life physics, the most advanced cue sports AI ever devised and TV-authentic presentation & commentary.' FROM games WHERE igdb_id = 175858 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 175858 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
