INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laruaville 10', 'Merlin, the mightiest wizard of antiquity, has awoke and built himself a castle. Unfortunately, ancient castles were poorly designed with high humidity, dark corridors and drafty rooms! Merlin is smart however, and he has stolen the Sun and placed it in the castle for him to enjoy alone! But what about the rest of us? Maybe a friend from Merlin’s past can convince him to return the Sun to its rightful place.' FROM games WHERE igdb_id = 136565 ON CONFLICT (game_id, language_code) DO NOTHING;
