INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'October Night Games', 'Will you save the world, or offer it up to the Great Old Ones? October Night Games is a digital board game where everyone is a cultist working for one of two different sides. Scour the town for cursed ingredients and make deals with inscrutable entities in preparation for a reckoning on Halloween.' FROM games WHERE igdb_id = 138514 ON CONFLICT (game_id, language_code) DO NOTHING;
