INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyberception', 'Fast-paced, brutal, cyberpunk FPS shooter game. Fight for your right to exercise free will again. Fight through hordes of mindless crooks of the Corporation to reach the executive floor and put an end to contract they put on your head. There will be blood and pieces of neuro fiber everywhere.' FROM games WHERE igdb_id = 132482 ON CONFLICT (game_id, language_code) DO NOTHING;
