INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Swirl', 'Blue Swirl is an underwater endless runner featuring procedurally generated environments. Players navigate an infinite abyss, dodging obstacles such as sharks, coral reefs, and rocks using one-touch controls. The game includes a Campaign mode for skill progression and a hardcore Infinite mode for high-score competition. Key features include a dynamic soundtrack that adapts to gameplay speed, collectible fish skins, and a variety of strategic power-ups.' FROM games WHERE igdb_id = 297526 ON CONFLICT (game_id, language_code) DO NOTHING;
