INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neko Yume', 'Neko Yume is an ambient exploration game heavily inspired by games like LSD Dream Emulator and Yume Nikki. Explore a cat-filled dream with a day/night cycle and dozens of randomized events. Even if you have explored an area once, there is no guarantee that it will be the same upon your return.' FROM games WHERE igdb_id = 166503 ON CONFLICT (game_id, language_code) DO NOTHING;
