INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bisque Doll', 'BISQUE DOLL is a Hong Kong urban legend About a year ago My mother bought a pair of bisque dolls That''s for my sister''s room decoration My grandma told me since I was young When you put away the bisque doll Don''t keep her in a dark corner Or in the cabinet that nobody cares about' FROM games WHERE igdb_id = 168533 ON CONFLICT (game_id, language_code) DO NOTHING;
