INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('poltergeist-crusader', 146750, '2020-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5apd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb95.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poltergeist Crusader', 'Crawl into the endless dungeon filled with ghosts and nightmare creatures. Use the holy cross and samurai sword of your grand father to slay the evil beings. However, remember that every tunnel you encounter will be a totally different maze of darkness. Are you able to survive the almighty power of Poltergeist and reach the final portal? Key game features: - Encounter dozens of various enemies on your way; - Traverse and explore hundreds of miles (kilometres) of dark corridors; - Slay your opponents with ancient samurai sword; - Take part in duels with Poltergeists and use the holy bolt to cast them away; - Use potions and consumable items to cure your character; - Fantastic arcade game that will provide a lot of entertainment for you and your friends (especially during Halloween!)' FROM games WHERE igdb_id = 146750 ON CONFLICT (game_id, language_code) DO NOTHING;
