INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zgr3d', 'Zgr3d is an adaption of the DOS game Kret for the Amiga. The aim of the player is to destroy Tetris-like blocks that fall down from the top of the screen. With each move the whole line of blocks drops down one line unless it cannot go further because the composition of the game field does not allow it. The player needs to move carefully through the field destroying the blocks without being squashed.' FROM games WHERE igdb_id = 241657 ON CONFLICT (game_id, language_code) DO NOTHING;
