INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro Blox Revisited', 'Astro Blox Revisited is an adaptation of Soko-Ban. The aim for the player is to place boxes in the designated places. There are lots of new ideas that change the Soko-Ban aspect. Some fields create inversions which either help or make the task much more difficult.' FROM games WHERE igdb_id = 241655 ON CONFLICT (game_id, language_code) DO NOTHING;
