INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neighbourhood Cat', 'In the peak of lockdown, you are Neighbourhood Cat, the only one around who still has the freedom to go outside. Roam the streets, visit your neighbours, listen to their stories, and spread a bit of comfort and charm. After all, you are a cat. That''s what you do.' FROM games WHERE igdb_id = 214510 ON CONFLICT (game_id, language_code) DO NOTHING;
