INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suguru Nature', 'Suguru Nature is a great logic puzzle with two simple rules. The cells in each puzzle grid are divided into groups, and each group contains the numbers from 1 to N, where N is the number of cells in the group. Thus, a group containing 5 cells will contain numbers from 1 to 5. The second rule is that no two adjacent cells, including diagonal, can contain the same number.' FROM games WHERE igdb_id = 147617 ON CONFLICT (game_id, language_code) DO NOTHING;
